// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { addProductToCart, incrementCartQuantity } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await addProductToCart(page);
    await expect(page.getByTestId("cart-heading")).toContainText("Cart (1)");

    // The PR description states that changing a quantity "recomputes the line total and
    // cart subtotal client-side". Capture the Total row before the change so the expected
    // value after it is derived, not hardcoded (shipping is quoted by the backend).
    const cartTotal = page.locator(".cart-summary-total-row .text-right");
    const totalBefore = parseFloat((await cartTotal.innerText()).replace(/[^0-9.]/g, ""));

    await incrementCartQuantity(page);
    await expect(page.locator(".qty-control input.qty-input")).toHaveValue("2");

    // One extra unit of a $19.99 item must raise the cart total by exactly 19.99.
    await expect(cartTotal).toHaveText(`$${(totalBefore + 19.99).toFixed(2)}`);
});
